const std = @import("std");

fn swap(arr: []u8, i: usize, j: usize) void {
    const temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

fn permute(arr: []u8, left: usize, right: usize) void {
    if (left == right) {
        std.debug.print("{s}\n", .{arr});
        return;
    }
    for (left..right + 1) |i| {
        swap(arr, left, i);
        permute(arr, left + 1, right);
        swap(arr, left, i);
    }
}

pub fn main() !void {
    var text = [_]u8{ 'A', 'B', 'C' };
    permute(&text, 0, 2);
}
